(()=>{const o=document.querySelector(".scroll-top");if(!o)return;const s=320;function t(){const n=(window.scrollY||document.documentElement.scrollTop)>s;o.hidden=!n,o.classList.toggle("scroll-top--visible",n)}o.addEventListener("click",()=>{const e=window.matchMedia("(prefers-reduced-motion: reduce)").matches;window.scrollTo({top:0,behavior:e?"auto":"smooth"})}),window.addEventListener("scroll",t,{passive:!0}),t()})();
